using System.Net;
using System.Net.Http.Json;
using System.Text.Json;
using AeroScience.Missions;
using AeroScience.Organization;
using AeroScience.Shared;
using Microsoft.EntityFrameworkCore;
using Microsoft.Extensions.DependencyInjection;
using Xunit;
namespace AeroScience.Tests;

public sealed partial class OrganizationConnectionIntegrationTests
{
    const string Workflow=Progress+"/workflow";
    static Task<T> WorkflowGet<T>(SubmissionFixture f,string path)=>ReviewGet<T>(f.Server,Workflow+path);
    static async Task<ProgramPolicyView> WorkflowPolicy(SubmissionFixture f,Guid program,ProgramWorkflowPolicy policy,int revision=0)=>(await f.Server.Post(Workflow+$"/programs/{program}/policy",new ProgramPolicyCommand(1,Guid.NewGuid(),revision,policy,"Explicit organization workflow policy, never aircraft certification."))).Deserialize<ProgramPolicyView>(WireJson.Options)!;
    static PhaseRequirement PhaseRule(OrganizationOpportunitySnapshot card,bool waive=true,bool exceptions=false)=>new(card.Id,card.Revision,PreflightReadiness.Hash(card),RequiredPilots:card.Policy.RequiredDistinctPilots,AllowWaivers:waive,AllowExceptions:exceptions,CountAuthorizedPartialContributors:exceptions);
    static async Task<TestPhaseSnapshot> WorkflowPhase(SubmissionFixture f,OrganizationOpportunitySnapshot card,string name,int sequence,Guid[] prerequisites,PhaseAdvancement mode=PhaseAdvancement.ManagerRelease)=> (await f.Server.Post(Workflow+$"/programs/{card.ProgramId}/phases",new PhaseSaveCommand(1,Guid.NewGuid(),0,new(1,name,"Explicit simulated testing objective",sequence,mode,prerequisites,[PhaseRule(card)]),"Published card requirements reviewed by manager."))).Deserialize<TestPhaseSnapshot>(WireJson.Options)!;
    static WorkflowExceptionCommand Waiver(OrganizationOpportunitySnapshot card,ProgramPolicyView policy,TestPhaseSnapshot? phase=null,string? key=null)=>new(1,Guid.NewGuid(),policy.Revision,card.Id,card.Revision,PreflightReadiness.Hash(card),WorkflowExceptionKind.RequirementWaiver,"Unsupported or unmet organizational requirement.","Manager permits this exact requirement for the stated purpose only.","No successful measurement or independent pilot is invented.",key,phase?.Id,phase?.DefinitionRevision,Confirm:true);
    static async Task<WorkflowExceptionSnapshot> WorkflowAuthorize(SubmissionFixture f,Guid program,WorkflowExceptionCommand command)=>(await f.Server.Post(Workflow+$"/programs/{program}/exceptions",command)).Deserialize<WorkflowExceptionSnapshot>(WireJson.Options)!;
    static async Task<TestPhaseSnapshot> WorkflowDecision(SubmissionFixture f,Guid program,Guid phase,PhaseCommandAction action)
    {var current=(await WorkflowGet<ProgramWorkflowView>(f,$"/programs/{program}")).ActivePhases.Single(p=>p.Id==phase);return(await f.Server.Post(Workflow+$"/programs/{program}/phases/{phase}/commands",new PhaseStateCommand(1,Guid.NewGuid(),current.Revision,action,"Manager reviewed current readiness and retained original evidence.",true))).Deserialize<TestPhaseSnapshot>(WireJson.Options)!;}
    static async Task<SubmissionDraft> WorkflowSend(SubmissionFixture f,PersonalResearchAttempt attempt,Guid connection)
    {
        var row=f.Store.SaveSubmissionDraft(new(1,Guid.NewGuid(),0,attempt.FlightId,[attempt.Id],null,"Actual original evidence selected for workflow review",connection),f.Science);await f.Desktop.RefreshSubmissionPolicies(connection,row,f.Store,default);row=f.Store.SaveSubmissionDraft(MissionStore.SubmissionRequest(row),f.Science);var p=f.Store.PreviewSavedSubmission(row.Id,f.Science);await f.Desktop.ApproveSubmission(row.Id,new(1,row.Revision,p.ManifestSha256,p.PayloadSha256,p.PayloadBytes,connection,true),f.Store,f.Science,default);using var delivery=f.Delivery();row=await delivery.Send(row.Id,default);Assert.Equal(SubmissionDeliveryState.ServerReceived,row.State);return row;
    }
    static async Task<WorkflowExceptionCommand> ReceivedException(SubmissionFixture f,OrganizationOpportunitySnapshot card,ProgramPolicyView policy,SubmissionDraft row,bool partial=true)
    {var review=await ReviewGet<ResearchReviewSnapshot>(f.Server,ReviewPath(row.Receipt!.Id));return new(1,Guid.NewGuid(),policy.Revision,card.Id,card.Revision,PreflightReadiness.Hash(card),WorkflowExceptionKind.ApprovedWithExceptions,"The received attempt did not achieve the published hold.","Accept this exact actual contribution for organizational workflow under the explicit partial-credit policy.","Original measured failure remains failed; this is not an aircraft safety finding.",RootReceiptId:row.Receipt.Id,LocalCardId:row.Manifest.Cards.Single().CardId,Evidence:[new(row.Receipt.Id,"*")],CountAsPartialContributor:partial,Confirm:true,ExpectedReviewRevision:review.Summary.Revision,ExpectedReviewHeadSha256:review.Requests is not null?(await ReviewGet<ResearchReviewHistory>(f.Server,ReviewPath(row.Receipt.Id)+"/history")).HeadSha256:null);}
    [PostgresFact] public async Task AutomaticPhaseReleaseRetainsExactPartialReceiptProofAndNeverChangesInsufficientOriginalEvidence()
    {
        await using var f=await SubmissionFixture.Create();var c=await f.Card(incomplete:true);var policy=await WorkflowPolicy(f,c.Published.ProgramId,new(PhaseGatesEnabled:true));var phase=(await f.Server.Post(Workflow+$"/programs/{c.Published.ProgramId}/phases",new PhaseSaveCommand(1,Guid.NewGuid(),0,new(1,"Bounded partial-work policy","Documented organization workflow only",1,PhaseAdvancement.AutomaticAfterApprovals,[],[PhaseRule(c.Published,exceptions:true)]),"Explicit policy allows an actual partial received contribution."))).Deserialize<TestPhaseSnapshot>(WireJson.Options)!;var result=await f.Record(c.Prepared,3);Assert.Equal(ResearchAttemptOutcome.InsufficientEvidence,result.Outcome);var received=await WorkflowSend(f,result,f.Upload);var command=(await ReceivedException(f,c.Published,policy,received)) with{PhaseId=phase.Id,ExpectedPhaseDefinitionRevision=phase.DefinitionRevision};var decision=await WorkflowAuthorize(f,c.Published.ProgramId,command);var state=Assert.Single((await WorkflowGet<ProgramWorkflowView>(f,$"/programs/{c.Published.ProgramId}")).ActivePhases);Assert.True(state.Authorized);Assert.Equal(0,state.Requirements.Single().ApprovedScientificContributors);Assert.Equal(1,state.Requirements.Single().AuthorizedPartialContributors);
        var source=await WorkflowGet<TestPhaseSnapshot>(f,$"/phases/{phase.Id}/revisions/{state.Revision}");var proof=Assert.Single(Assert.Single(source.Proof!.Support).Contributions);Assert.Equal(received.Receipt!.Id,proof.RootReceiptId);Assert.Equal(c.Claim.Id,proof.ClaimId);Assert.Equal(decision.Id,proof.ExceptionId);Assert.Equal(command.ExpectedReviewRevision,proof.ReviewRevision);Assert.Equal(command.ExpectedReviewHeadSha256,proof.ReviewHeadSha256);Assert.Equal(0,(await ProgressGet<CampaignProgressView>(f,$"/campaigns/{c.Published.CampaignId}")).Totals.ApprovedPilotContributions);Assert.Empty((await ProgressGet<OrganizationPage<CoverageGroup>>(f,$"/campaigns/{c.Published.CampaignId}/coverage/groups")).Items);Assert.Equal(ResearchAttemptOutcome.InsufficientEvidence,f.Store.ResearchAttempt(result.Id).Outcome);
        await f.Restart();Assert.True(Assert.Single((await WorkflowGet<ProgramWorkflowView>(f,$"/programs/{c.Published.ProgramId}")).ActivePhases).Authorized);Assert.Equal(source.Proof.Sha256,Assert.Single((await WorkflowGet<ProgramWorkflowView>(f,$"/programs/{c.Published.ProgramId}")).ActivePhases).AuthorizationSha256);
    }
    [PostgresFact] public async Task PhaseCanUseApprovedIndividualPointAndExactWaiverWhileWholeCardAndScientificCoverageStayIncomplete()
    {
        await using var f=await SubmissionFixture.Create();var c=await f.Card(FlightRegimeEvaluation.ProcedureTemplate,incomplete:true);var start=DateTimeOffset.UtcNow;var time=start;var coordinator=new MissionCoordinator(f.Store,1000,utcNow:()=>time);void Observe(int second){time=start.AddSeconds(second);var frame=SubmissionFixture.Frame(time);coordinator.Apply(new(new(ConnectionState.Connected,frame.Source,"Explicit synthetic point recording",time),frame));}Observe(0);var flight=coordinator.Start(new("One supported original point, another unattempted",PlanId:c.Prepared.Plan.Id));var card=c.Prepared.Card;
        void Control(ResearchCardAction action){var state=coordinator.PersonalResearch(flight.Id);coordinator.ControlPersonalResearch(new(1,flight.Id,Guid.NewGuid(),state.Revision,action,card.Id,state.Cards.Single().OpenAttempt?.Id,action==ResearchCardAction.BeginAttempt?card.Procedure!.Points[0].Id:null));}
        Control(ResearchCardAction.Activate);Observe(1);Control(ResearchCardAction.BeginAttempt);for(var i=2;i<=12;i++)Observe(i);Control(ResearchCardAction.EndAttempt);Observe(13);await Task.Delay(TimeSpan.FromSeconds(13));coordinator.End(flight.Id);var result=f.Store.EvaluateResearchAttempt(new(Guid.NewGuid(),flight.Id,start,time,CardId:card.Id));Assert.Equal(ResearchAttemptOutcome.InsufficientEvidence,result.Outcome);var row=await WorkflowSend(f,result,f.Upload);var requirements=(await WorkflowGet<PublishedWorkflowCard>(f,$"/cards/{c.Published.Id}?revision={c.Published.Revision}")).Requirements;await ReviewCommand(f,row,ResearchReviewAction.Approve,"This independently evaluated original point fulfilled its published hold; the other point did not.",new(card.Id,requirements[0].Key),[new(row.Receipt!.Id,"*")]);
        var policy=await WorkflowPolicy(f,c.Published.ProgramId,new(PhaseGatesEnabled:true));var phase=(await f.Server.Post(Workflow+$"/programs/{c.Published.ProgramId}/phases",new PhaseSaveCommand(1,Guid.NewGuid(),0,new(1,"Independent point objectives","Approved point and separately waived objective",1,PhaseAdvancement.ManagerRelease,[],[PhaseRule(c.Published,waive:false) with{RequirementKey=requirements[0].Key},PhaseRule(c.Published) with{RequirementKey=requirements[1].Key}]),"Exact original point IDs and issued revision."))).Deserialize<TestPhaseSnapshot>(WireJson.Options)!;var initial=Assert.Single((await WorkflowGet<ProgramWorkflowView>(f,$"/programs/{c.Published.ProgramId}")).ActivePhases);Assert.Equal(1,initial.Requirements[0].ApprovedScientificContributors);Assert.False(initial.Ready);var waiver=await WorkflowAuthorize(f,c.Published.ProgramId,Waiver(c.Published,policy,phase,requirements[1].Key));Assert.Null(waiver.PilotId);var ready=Assert.Single((await WorkflowGet<ProgramWorkflowView>(f,$"/programs/{c.Published.ProgramId}")).ActivePhases);Assert.True(ready.Ready);Assert.Equal(0,ready.Requirements[1].DistinctOrganizationalContributors);await WorkflowDecision(f,c.Published.ProgramId,phase.Id,PhaseCommandAction.Release);
        Assert.Equal(0,(await ProgressGet<CampaignProgressView>(f,$"/campaigns/{c.Published.CampaignId}")).Totals.ApprovedPilotContributions);Assert.Empty((await ProgressGet<OrganizationPage<CoverageGroup>>(f,$"/campaigns/{c.Published.CampaignId}/coverage/groups")).Items);await f.Restart();Assert.True(Assert.Single((await WorkflowGet<ProgramWorkflowView>(f,$"/programs/{c.Published.ProgramId}")).ActivePhases).Authorized);await ReviewCommand(f,row,ResearchReviewAction.Reject,"The original point approval is withdrawn without modifying the original telemetry.",new(card.Id,requirements[0].Key));Assert.False(Assert.Single((await WorkflowGet<ProgramWorkflowView>(f,$"/programs/{c.Published.ProgramId}")).ActivePhases).Authorized);Assert.Equal(ResearchAttemptOutcome.InsufficientEvidence,f.Store.ResearchAttempt(result.Id).Outcome);
    }
    [PostgresFact] public async Task ReceivedFailedAttemptCanHaveAuthorizedPartialCreditWithoutBecomingScientificPassOrCoverage()
    {
        await using var f=await SubmissionFixture.Create();var parent=await RealOpportunity(f.Server,FlightRegimeEvaluation.CustomTemplate);var card=await ProgressCard(f,parent,"Two pilot operating-condition assessment",new(OrganizationParticipation.MultiPilot,2,2,true,[OrganizationRoles.Administrator,OrganizationRoles.Pilot],"Exact original evidence and independent approvals"));var policy=await WorkflowPolicy(f,card.ProgramId,new(AllowCampaignWaivers:true,AllowCampaignExceptions:true,CountAuthorizedPartialContributors:true));var adminClaim=await BrowserClaim(f.Server,card);var preparation=await f.Desktop.PreviewMission(f.Read,adminClaim.Id,new(),f.Store,default);var first=await f.Desktop.PrepareMission(f.Read,adminClaim.Id,MissionSave(preparation),f.Store,default);var passed=await f.Record(first,31);Assert.Equal(ResearchAttemptOutcome.Pass,passed.Outcome);var approved=await WorkflowSend(f,passed,f.Upload);await ReviewCommand(f,approved,ResearchReviewAction.Approve,"Actual supported original hold met the requirement.",new(first.Card.Id,"conditions"),[new(approved.Receipt!.Id,"*")]);
        using var pilot=await ProgressPilot(f,"exception-contributor");var server=new Server(f.Server.App,pilot,f.Server.Origin,f.Database);var claim=await BrowserClaim(server,card);var upload=await Connect(f.Desktop,server,OrganizationDesktopPermission.SubmitEvidence);var plan=await f.Desktop.PreviewMission(upload,claim.Id,new(),f.Store,default);var second=await f.Desktop.PrepareMission(upload,claim.Id,MissionSave(plan),f.Store,default);var failed=await f.Record(second,31,fail:true);Assert.Equal(ResearchAttemptOutcome.Fail,failed.Outcome);var originalHash=PreflightReadiness.Hash(failed);var rejected=await WorkflowSend(f,failed,upload);await ReviewCommand(f,rejected,ResearchReviewAction.Reject,"Original IAS did not satisfy the published continuous hold.",new(second.Card.Id,"conditions"));
        var path=$"/campaigns/{card.CampaignId}";var coverageBefore=await ProgressGet<OrganizationPage<CoverageGroup>>(f,path+"/coverage/groups");var command=await ReceivedException(f,card,policy,rejected);var exception=await WorkflowAuthorize(f,card.ProgramId,command);Assert.Contains(exception.OriginalOutcomes,o=>o.Outcome==ResearchAttemptOutcome.Fail);Assert.Equal(claim.Id,exception.ClaimId);Assert.True(exception.Definition.CountAsPartialContributor);Assert.Equal(ResearchAttemptOutcome.Fail,f.Store.ResearchAttempt(failed.Id).Outcome);
        var progress=(await WorkflowGet<CampaignWorkflowView>(f,path)).Cards.Items.Single(r=>r.Requirement.OpportunityId==card.Id);Assert.Equal(1,progress.ApprovedScientificContributors);Assert.Equal(1,progress.AuthorizedPartialContributors);Assert.Equal(2,progress.DistinctOrganizationalContributors);Assert.True(progress.Fulfilled);Assert.Equal(1,(await ProgressGet<CampaignProgressView>(f,path)).Totals.ApprovedPilotContributions);Assert.Equal(0,(await ProgressGet<CampaignProgressView>(f,path)).Totals.CompletedCards);var coverageAfter=await ProgressGet<OrganizationPage<CoverageGroup>>(f,path+"/coverage/groups");Assert.Equal(JsonSerializer.Serialize(coverageBefore,WireJson.Options),JsonSerializer.Serialize(coverageAfter,WireJson.Options));
        var repeated=await WorkflowSend(f,failed,upload);await ReviewCommand(f,repeated,ResearchReviewAction.Reject,"Same original failed attempt in a second explicitly received package.",new(second.Card.Id,"conditions"));await WorkflowAuthorize(f,card.ProgramId,await ReceivedException(f,card,policy,repeated));Assert.Equal(2,(await WorkflowGet<CampaignWorkflowView>(f,path)).Cards.Items.Single(r=>r.Requirement.OpportunityId==card.Id).DistinctOrganizationalContributors);
        var summary=await pilot.GetFromJsonAsync<OrganizationPage<WorkflowExceptionView>>(Workflow+$"/programs/{card.ProgramId}/exceptions",WireJson.Options);Assert.All(summary!.Items,e=>{Assert.Null(e.ManagerDetails);Assert.Contains(e.OriginalOutcomes,o=>o.Outcome==ResearchAttemptOutcome.Fail);Assert.StartsWith("Contributor ",e.Contributor);});var publicJson=JsonSerializer.Serialize(summary,WireJson.Options);Assert.DoesNotContain("claimId",publicJson);Assert.DoesNotContain("rootReceiptId",publicJson);Assert.DoesNotContain("pilotId",publicJson);Assert.DoesNotContain(f.Vault.Read(upload)!,publicJson);using(var denied=await ReviewSend(f.Server,Workflow+$"/programs/{card.ProgramId}/exceptions",command with{RequestId=Guid.NewGuid()},pilot))Assert.Equal(HttpStatusCode.Forbidden,denied.StatusCode);
        await ReviewCommand(f,rejected,ResearchReviewAction.Reject,"A superseding finding changes the original-card review signature.",new(second.Card.Id,"conditions"));var decisions=await WorkflowGet<OrganizationPage<WorkflowExceptionView>>(f,$"/programs/{card.ProgramId}/exceptions");Assert.False(decisions.Items.Single(e=>e.Id==exception.Id).Effective);var replacement=(await ReceivedException(f,card,policy,rejected)) with{SupersedesId=exception.Id,ExpectedSupersededRevision=exception.Revision};var replaced=await WorkflowAuthorize(f,card.ProgramId,replacement);Assert.NotEqual(exception.Id,replaced.Id);Assert.Equal(2,(await WorkflowGet<OrganizationPage<WorkflowHistoryView>>(f,$"/history/{exception.Id}")).Items.Length);await f.Restart();Assert.Equal(2,(await WorkflowGet<CampaignWorkflowView>(f,path)).Cards.Items.Single(r=>r.Requirement.OpportunityId==card.Id).DistinctOrganizationalContributors);Assert.Equal(originalHash,PreflightReadiness.Hash(f.Store.ResearchAttempt(failed.Id)));
    }
