        using var native=new HttpClient{BaseAddress=new(f.Server.Origin)};native.DefaultRequestHeaders.Authorization=new("Bearer",f.Vault.Read(f.Read));var read=await native.GetFromJsonAsync<ProgramWorkflowView>($"/api/member/research-progress/workflow/programs/{program}",WireJson.Options);Assert.False(read!.CanManage);using(var denied=await native.PostAsJsonAsync($"/api/member/research-progress/workflow/programs/{program}/exceptions",Waiver(c.Published,policy),WireJson.Options))Assert.Equal(HttpStatusCode.Forbidden,denied.StatusCode);
        var edit=(await f.Server.Post($"/api/organization/opportunities/{c.Published.Id}/campaigns/{c.Published.CampaignId}",new OrganizationOpportunityRequest(1,Guid.NewGuid(),c.Published.Revision,c.Published.CampaignRevision,c.Published.Name,"New immutable publication",c.Published.Objective,c.Published.Instructions,c.Published.Policy),HttpMethod.Put)).Deserialize<OrganizationOpportunitySnapshot>(WireJson.Options)!;var publication=(await f.Server.Post($"/api/organization/opportunities/{edit.Id}/publish",new OrganizationPublishRequest(1,Guid.NewGuid(),edit.Revision))).Deserialize<OrganizationOpportunitySnapshot>(WireJson.Options)!;var fresh=(await WorkflowGet<CampaignWorkflowView>(f,$"/campaigns/{c.Published.CampaignId}")).Cards.Items.Single(r=>r.Requirement.OpportunityId==publication.Id);Assert.False(fresh.Fulfilled);Assert.Equal(0,fresh.ActiveWaivers);
        var current=(await WorkflowGet<ProgramWorkflowView>(f,$"/programs/{program}")).ActivePhases.Single();var revised=(await f.Server.Post(Workflow+$"/programs/{program}/phases/{phase.Id}",new PhaseSaveCommand(1,Guid.NewGuid(),current.Revision,current.Definition with{Requirements=[PhaseRule(publication)]},"Explicitly adopt the new published card for future organizational work."),HttpMethod.Put)).Deserialize<TestPhaseSnapshot>(WireJson.Options)!;Assert.False(Assert.Single((await WorkflowGet<ProgramWorkflowView>(f,$"/programs/{program}")).ActivePhases).Ready);Assert.False((await WorkflowGet<OrganizationPage<WorkflowExceptionView>>(f,$"/programs/{program}/exceptions")).Items.Single(e=>e.Id==first.Id).Effective);using(var stale=await ReviewSend(f.Server,Workflow+$"/programs/{program}/exceptions",Waiver(publication,policy,phase)))Assert.Equal(HttpStatusCode.Conflict,stale.StatusCode);
        await using(var other=await SubmissionFixture.Create()){using var hidden=await other.Server.Browser.GetAsync(Workflow+$"/programs/{program}");Assert.Equal(HttpStatusCode.NotFound,hidden.StatusCode);}await f.Server.Post("/api/organization/members/"+updated.UserId,new OrganizationMemberRequest(1,Guid.NewGuid(),updated.Revision,updated.Role,OrganizationMembershipState.Suspended),HttpMethod.Put);using(var revoked=await reviewer.GetAsync(Workflow+$"/programs/{program}"))Assert.Equal(HttpStatusCode.Unauthorized,revoked.StatusCode);
    }
    [PostgresFact] public async Task WorkflowHistoryHasNoLifetimePageCeilingAndPreservesImmutableOriginalDecisions()
    {
        await using var f=await SubmissionFixture.Create();var c=await f.Card();var program=c.Published.ProgramId;await WorkflowPolicy(f,program,new(PhaseGatesEnabled:true));var phase=await WorkflowPhase(f,c.Published,"Paged managerial history",1,[]);for(var i=0;i<21;i++)await WorkflowDecision(f,program,phase.Id,PhaseCommandAction.Hold);var page=await WorkflowGet<OrganizationPage<WorkflowHistoryView>>(f,$"/history/{phase.Id}");Assert.Equal(20,page.Items.Length);Assert.Equal(20,page.NextOffset);var next=await WorkflowGet<OrganizationPage<WorkflowHistoryView>>(f,$"/history/{phase.Id}?offset=20");Assert.Equal(2,next.Items.Length);Assert.Null(next.NextOffset);Assert.Equal(22,page.Items.Concat(next.Items).Select(e=>e.Revision).Distinct().Count());
        using(var scope=f.Server.App.Services.CreateScope()){var db=scope.ServiceProvider.GetRequiredService<OrganizationDatabase>();var original=await db.Revisions.SingleAsync(r=>r.ResourceId==phase.Id&&r.Revision==1);original.SnapshotJson="changed";await Assert.ThrowsAsync<InvalidOperationException>(()=>db.SaveChangesAsync());}await f.Restart();Assert.Equal(page.Items.Select(p=>p.Sha256),(await WorkflowGet<OrganizationPage<WorkflowHistoryView>>(f,$"/history/{phase.Id}")).Items.Select(p=>p.Sha256));
    }
    [PostgresFact] public async Task ManagerAuthorizationIsRecheckedAfterWaitingForTheRealPostgresWorkflowLock()
    {
        await using var f=await SubmissionFixture.Create();var c=await f.Card();using var browser=await ProgressPilot(f,"revocable-workflow-manager");var member=(await ReviewGet<OrganizationPage<OrganizationMemberView>>(f.Server,"/api/organization/members")).Items.Single(m=>m.Name=="revocable-workflow-manager");await f.Server.Post("/api/organization/members/"+member.UserId,new OrganizationMemberRequest(1,Guid.NewGuid(),member.Revision,OrganizationRoles.Manager,OrganizationMembershipState.Active),HttpMethod.Put);using(var login=await ReviewSend(f.Server,"/api/sign-in",new OrganizationLoginRequest(member.Name,"ResearchOnly!2026Flight"),browser))Assert.True(login.IsSuccessStatusCode);
        var connection=new Npgsql.NpgsqlConnectionStringBuilder(System.Environment.GetEnvironmentVariable("AEROSCIENCE_ORG_TEST_DATABASE")){Database=f.Database};await using var holder=new Npgsql.NpgsqlConnection(connection.ConnectionString);await holder.OpenAsync();await using var transaction=await holder.BeginTransactionAsync();await using(var take=new Npgsql.NpgsqlCommand("SELECT pg_advisory_xact_lock(7014001)",holder,transaction))await take.ExecuteNonQueryAsync();var pending=ReviewSend(f.Server,Workflow+$"/programs/{c.Published.ProgramId}/policy",new ProgramPolicyCommand(1,Guid.NewGuid(),0,new(AllowCampaignWaivers:true),"This must fail if manager authority is revoked while waiting."),browser);await using var observer=new Npgsql.NpgsqlConnection(connection.ConnectionString);await observer.OpenAsync();var deadline=DateTime.UtcNow.AddSeconds(10);bool waiting=false;while(DateTime.UtcNow<deadline){await using var query=new Npgsql.NpgsqlCommand("SELECT EXISTS (SELECT 1 FROM pg_stat_activity WHERE datname=current_database() AND wait_event='advisory' AND query LIKE '%7014001%')",observer);waiting=(bool)(await query.ExecuteScalarAsync())!;if(waiting)break;await Task.Delay(20);}Assert.True(waiting,"The real request must reach the authoritative workflow/membership lock.");
        using(var scope=f.Server.App.Services.CreateScope()){var db=scope.ServiceProvider.GetRequiredService<OrganizationDatabase>();await db.Memberships.Where(m=>m.UserId==member.UserId).ExecuteUpdateAsync(set=>set.SetProperty(m=>m.Role,OrganizationRoles.Pilot));}await transaction.CommitAsync();using var denied=await pending;Assert.Equal(HttpStatusCode.Forbidden,denied.StatusCode);Assert.Equal(0,(await WorkflowGet<ProgramWorkflowView>(f,$"/programs/{c.Published.ProgramId}")).Policy.Revision);
    }
